## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/thaLogic.ts`

```typescript
export type AffectedSide = "right" | "left" | "bilateral";

export type THAInput = {
  age: string; bmi: string; affectedSide: AffectedSide | ""; painScore: string;
  harrisPainScore?: string; harrisADLScore?: string;
  kellgrenLawrence?: string; symptomDurationMonths?: string;
  conservativeTherapyMonths: string; conservativeTherapies: string[];
  comorbidities: string[]; functionalLimitations: string[];
  radiographicFindings: string[];
  activeInfection: boolean; activeHipInfection?: boolean;
  severeVascularDisease: boolean; medicallyUnfit?: boolean;
  avascularNecrosis?: boolean; abductorInsufficiency: boolean; priorHipInfection: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessTHA(input: THAInput) {
  const bmi = parseFloat(input.bmi) || 0;
  const harrisPain = parseFloat(input.harrisPainScore || '0') || 44;
  const harrisADL = parseFloat(input.harrisADLScore || '0') || 47;
  const kl = parseInt(input.kellgrenLawrence || '0') || 0;
  const conservMonths = parseFloat(input.conservativeTherapyMonths) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active systemic infection — absolute contraindication");
  if (input.activeHipInfection) contraindications.push("Active hip joint infection — absolute contraindication");
  if (input.severeVascularDisease) contraindications.push("Severe peripheral vascular disease — high surgical risk");
  if (input.medicallyUnfit) contraindications.push("Medically unfit for surgery — requires optimization");

  if (contraindications.length > 0) {
    return { recommendation: "THA Contraindicated or Requires Optimization", cor: "III" as COR, loe: "C", urgency: "Contraindicated", rationale: ["One or more absolute or relative contraindications identified."], contraindications, optimizationSteps: ["Address contraindications before proceeding with THA"] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  if (input.avascularNecrosis) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Avascular necrosis of the femoral head — THA is the definitive treatment for advanced AVN");
    rationale.push("Earlier intervention improves outcomes by preventing femoral head collapse");
  } else if (kl >= 3 && harrisPain <= 20 && conservMonths >= 3) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Severe hip OA (KL ≥3) with significant pain and functional limitation");
    rationale.push("Harris Hip Score pain component indicates severe disability");
    rationale.push("Conservative therapy trial completed");
  } else if (kl >= 2 && harrisPain <= 30 && conservMonths >= 3) {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Moderate hip OA with meaningful pain and functional limitation");
    rationale.push("THA is a reasonable option after shared decision-making");
  } else {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("Criteria for THA not fully met — continue conservative management");
    optimizationSteps.push("Continue PT, weight management, and analgesics for ≥3 months");
    optimizationSteps.push("Consider intraarticular corticosteroid injection");
  }

  if (bmi > 40) optimizationSteps.push("BMI >40: weight loss recommended before elective THA");
  if (input.comorbidities.includes("diabetes")) optimizationSteps.push("Optimize glycemic control (HbA1c <8%)");
  if (input.comorbidities.includes("smoking")) optimizationSteps.push("Smoking cessation ≥4 weeks before surgery");

  return { recommendation: cor === "I" ? "THA Recommended" : cor === "IIa" ? "THA Reasonable" : "THA — Additional Criteria Needed", cor, loe: kl >= 3 ? "A" : "B", urgency, rationale, contraindications, optimizationSteps };
}
